                    if not all(grid[i][c] == 5 and grid[i][d] == 5
                               for i in range(r, b + 1)):
                        continue
                    if not all(grid[b][j] == 5 for j in range(c, d + 1)):
                        continue

                    # The top edge has exactly one opening.
                    gaps = [j for j in range(c, d + 1) if grid[r][j] != 5]
                    if len(gaps) != 1 or any(
                        grid[r][j] != 5 for j in range(c, d + 1)
                        if j != gaps[0]
